void vectorized_s275(int iterations, float aa[256][256], float bb[256][256], float cc[256][256])
{
    int loop_count = 10 * (iterations / 256);

    for (int nl = 0; nl < loop_count; nl++) {
        // Precompute condition mask for all columns
        int cond[256];
        for (int i = 0; i < 256; i++) {
            cond[i] = aa[0][i] > 0.f;
        }

        // Process each row sequentially (dependency in j direction)
        for (int j = 1; j < 256; j++) {
            // Unrolled vector-friendly loop across columns (4-wide)
            int i = 0;
            for (; i <= 252; i += 4) {
                float a0 = aa[j-1][i+0];
                float a1 = aa[j-1][i+1];
                float a2 = aa[j-1][i+2];
                float a3 = aa[j-1][i+3];

                float b0 = bb[j][i+0];
                float b1 = bb[j][i+1];
                float b2 = bb[j][i+2];
                float b3 = bb[j][i+3];

                float c0 = cc[j][i+0];
                float c1 = cc[j][i+1];
                float c2 = cc[j][i+2];
                float c3 = cc[j][i+3];

                float r0 = a0 + b0 * c0;
                float r1 = a1 + b1 * c1;
                float r2 = a2 + b2 * c2;
                float r3 = a3 + b3 * c3;

                if (cond[i+0]) aa[j][i+0] = r0;
                if (cond[i+1]) aa[j][i+1] = r1;
                if (cond[i+2]) aa[j][i+2] = r2;
                if (cond[i+3]) aa[j][i+3] = r3;
            }
            // Scalar cleanup tail
            for (; i < 256; i++) {
                if (cond[i]) {
                    aa[j][i] = aa[j-1][i] + bb[j][i] * cc[j][i];
                }
            }
        }
    }
}
